using System;

// class = reference type, struct = value type
class PointC { public int X; }
struct PointS { public int X; }

// A hand-written "record-like" class: value equality over its data (what a record generates)
sealed class Money : IEquatable<Money>
{
    public readonly int Amount; public readonly string Cur;
    public Money(int a, string c) { Amount = a; Cur = c; }
    public bool Equals(Money o) { return o != null && Amount == o.Amount && Cur == o.Cur; }
    public override bool Equals(object o) { return Equals(o as Money); }
    public override int GetHashCode() { return Amount * 31 + Cur.GetHashCode(); }
    public override string ToString() { return "Money { Amount = " + Amount + ", Cur = " + Cur + " }"; }
}

class Program
{
    static void Main()
    {
        PointC c1 = new PointC { X = 1 }; PointC c2 = c1;   // copies the reference
        c2.X = 99;
        Console.WriteLine("class: c1.X=" + c1.X + " (aliased)");

        PointS s1 = new PointS { X = 1 }; PointS s2 = s1;   // copies the whole value
        s2.X = 99;
        Console.WriteLine("struct: s1.X=" + s1.X + " (independent copy)");

        Console.WriteLine("class equality is identity: " + (new PointC { X = 1 }).Equals(new PointC { X = 1 }));
        Money a = new Money(5, "EUR"), b = new Money(5, "EUR");
        Console.WriteLine("record-like equality: " + a.Equals(b) + ", " + a);
    }
}

using System;
using System.Collections.Generic;

struct Counter { public int N; }

class Program
{
    static void Bump(Counter c) { c.N++; }              // works on a copy
    static void BumpRef(ref Counter c) { c.N++; }       // works on the original

    static void Main()
    {
        Counter a = new Counter { N = 1 };
        Bump(a);
        Console.WriteLine("after Bump (copy): " + a.N);
        BumpRef(ref a);
        Console.WriteLine("after BumpRef: " + a.N);

        int x = 42;
        object boxed = x;               // boxing: copies x into a new heap object
        x = 7;                          // does not change the box
        Console.WriteLine("x=" + x + " boxed=" + boxed);
        int back = (int)boxed;          // unboxing copies it out again
        Console.WriteLine("unboxed=" + back);

        // A mutable struct inside a List is returned by copy, so this would not even compile:
        // list[0].N = 5;
        List<Counter> list = new List<Counter> { new Counter { N = 1 } };
        Counter tmp = list[0]; tmp.N = 5;
        Console.WriteLine("list[0].N still " + list[0].N + ", copy has " + tmp.N);
    }
}

using System;
using System.Collections.Generic;

sealed class Order
{
    public readonly string Id;
    public readonly decimal Total;
    public readonly IReadOnlyList<string> Items;

    public Order(string id, decimal total, IEnumerable<string> items)
    {
        if (total < 0) throw new ArgumentException("total must be >= 0");  // validate once, here
        Id = id; Total = total;
        Items = new List<string>(items).AsReadOnly();   // defensive copy: caller's list can't leak in
    }

    // "with" equivalent: return a NEW instance, the old one is untouched
    public Order WithTotal(decimal t) { return new Order(Id, t, Items); }
    public override string ToString() { return Id + " total=" + Total + " items=" + string.Join(",", Items); }
}

class Program
{
    static void Main()
    {
        List<string> source = new List<string> { "pen", "ink" };
        Order o1 = new Order("A1", 10m, source);
        source.Add("hack");                       // does not affect o1 thanks to the copy
        Order o2 = o1.WithTotal(12m);
        Console.WriteLine(o1);
        Console.WriteLine(o2);
        try { o1.WithTotal(-1m); } catch (ArgumentException e) { Console.WriteLine("rejected: " + e.Message); }
        Console.WriteLine("same items object shared: " + ReferenceEquals(o1.Items, o2.Items));
    }
}

using System;

// A minimal Result type: failure is a value, not an exception
sealed class Result<T>
{
    public readonly bool Ok; public readonly T Value; public readonly string Error;
    Result(bool ok, T v, string e) { Ok = ok; Value = v; Error = e; }
    public static Result<T> Success(T v) { return new Result<T>(true, v, null); }
    public static Result<T> Fail(string e) { return new Result<T>(false, default(T), e); }
    // Bind chains steps and stops at the first failure
    public Result<U> Bind<U>(Func<T, Result<U>> f) { return Ok ? f(Value) : Result<U>.Fail(Error); }
}

class Program
{
    static Result<int> Parse(string s)
    {
        int n;
        return int.TryParse(s, out n) ? Result<int>.Success(n) : Result<int>.Fail("'" + s + "' is not a number");
    }
    static Result<int> Positive(int n) { return n > 0 ? Result<int>.Success(n) : Result<int>.Fail(n + " is not positive"); }

    static void Main()
    {
        string[] inputs = { "42", "abc", "-5" };
        foreach (string s in inputs)
        {
            Result<int> r = Parse(s).Bind(Positive);
            Console.WriteLine(s + " -> " + (r.Ok ? "ok " + r.Value : "error: " + r.Error));
        }
        // Throwing for the same expected failure is far slower when it is frequent
        int fails = 0;
        for (int i = 0; i < 2000; i++) { try { int.Parse("x"); } catch (FormatException) { fails++; } }
        Console.WriteLine("exceptions caught: " + fails + " (each one captures a stack trace)");
    }
}

using System;

class Resource : IDisposable
{
    readonly string name; bool disposed;
    public Resource(string n) { name = n; Console.WriteLine("open " + n); }

    public void Use()
    {
        if (disposed) throw new ObjectDisposedException(name);   // fail loudly after Dispose
        Console.WriteLine("using " + name);
    }

    public void Dispose()
    {
        Dispose(true);
        GC.SuppressFinalize(this);        // no finalizer needed once disposed
    }

    protected virtual void Dispose(bool disposing)
    {
        if (disposed) return;             // idempotent
        if (disposing) Console.WriteLine("dispose managed fields of " + name);
        Console.WriteLine("release unmanaged state of " + name);
        disposed = true;
    }

    ~Resource() { Dispose(false); }       // safety net only for owners of raw handles
}

class Program
{
    static void Main()
    {
        using (Resource r = new Resource("db"))   // Dispose runs even if Use throws
        {
            r.Use();
        }
        Resource r2 = new Resource("file");
        r2.Dispose();
        r2.Dispose();                             // second call does nothing
        try { r2.Use(); } catch (ObjectDisposedException e) { Console.WriteLine("caught ObjectDisposedException: " + e.ObjectName); }
    }
}

using System;
using System.Threading.Tasks;

class Program
{
    static async Task Fail(string msg)
    {
        await Task.Delay(10);
        throw new InvalidOperationException(msg);
    }

    static async Task Run()
    {
        Task a = Fail("first failure");
        Task b = Fail("second failure");
        try
        {
            await Task.WhenAll(a, b);          // await rethrows only the FIRST exception
        }
        catch (Exception e)
        {
            Console.WriteLine("caught: " + e.Message);
        }
        // the other exception is still on the task: inspect it, or you lose it
        Console.WriteLine("each original task also holds its own exception: " + a.Exception.InnerExceptions.Count
            + "+" + b.Exception.InnerExceptions.Count);

        Task both = Task.WhenAll(Fail("x"), Fail("y"));
        try { await both; } catch { }
        Console.WriteLine("WhenAll task holds " + both.Exception.InnerExceptions.Count + " exceptions");
    }

    static void Main()
    {
        // Main is synchronous here only because this demo has no sync context; in real
        // UI/ASP.NET code .GetAwaiter().GetResult() is the "sync over async" mistake.
        Run().GetAwaiter().GetResult();
    }
}

using System;
using System.Collections.Generic;

class BadKey                                   // Equals without GetHashCode
{
    public int Id;
    public override bool Equals(object o) { BadKey k = o as BadKey; return k != null && k.Id == Id; }
}

class GoodKey                                  // both overridden, consistent
{
    public int Id;
    public override bool Equals(object o) { GoodKey k = o as GoodKey; return k != null && k.Id == Id; }
    public override int GetHashCode() { return Id.GetHashCode(); }
}

class MutableKey
{
    public int Id;
    public override bool Equals(object o) { MutableKey k = o as MutableKey; return k != null && k.Id == Id; }
    public override int GetHashCode() { return Id; }
}

class Program
{
    static void Main()
    {
        HashSet<BadKey> bad = new HashSet<BadKey> { new BadKey { Id = 1 } };
        Console.WriteLine("BadKey found:  " + bad.Contains(new BadKey { Id = 1 }));    // false: different hash

        HashSet<GoodKey> good = new HashSet<GoodKey> { new GoodKey { Id = 1 } };
        Console.WriteLine("GoodKey found: " + good.Contains(new GoodKey { Id = 1 }));  // true

        MutableKey mk = new MutableKey { Id = 1 };
        HashSet<MutableKey> set = new HashSet<MutableKey> { mk };
        mk.Id = 2;                                   // hash changed while inside the set
        Console.WriteLine("after mutation, Contains(mk): " + set.Contains(mk));        // false: lost
        Console.WriteLine("but the set still holds " + set.Count + " item");
        Console.WriteLine("ordinal vs culture-free compare: " + string.Equals("a", "A", StringComparison.OrdinalIgnoreCase));
    }
}

using System;
using System.Collections.Generic;
using System.Linq;

class Program
{
    static int calls = 0;
    static int Expensive(int x) { calls++; return x * x; }

    static void Main()
    {
        List<int> data = new List<int> { 1, 2, 3 };
        IEnumerable<int> query = data.Select(Expensive);    // nothing runs yet
        Console.WriteLine("after defining query, calls = " + calls);

        int count = query.Count();                           // runs the pipeline
        int sum = query.Sum();                               // runs it AGAIN
        Console.WriteLine("count=" + count + " sum=" + sum + " calls = " + calls);

        data.Add(4);                                         // source changed before next enumeration
        Console.WriteLine("query now sees: " + string.Join(",", query));

        calls = 0;
        List<int> snapshot = data.Select(Expensive).ToList();  // materialise once
        int c2 = snapshot.Count; int s2 = snapshot.Sum();
        Console.WriteLine("snapshot count=" + c2 + " sum=" + s2 + " calls = " + calls);

        try { foreach (int x in data) if (x == 1) data.Add(99); }
        catch (InvalidOperationException) { Console.WriteLine("modifying the source while enumerating throws"); }
    }
}

using System;
using System.Collections.Generic;

class Program
{
    static void Main()
    {
        List<Func<int>> forLoop = new List<Func<int>>();
        for (int i = 0; i < 3; i++)
            forLoop.Add(() => i);               // captures the variable i, one shared variable
        Console.Write("for loop:     ");
        foreach (Func<int> f in forLoop) Console.Write(f() + " ");     // 3 3 3
        Console.WriteLine();

        List<Func<int>> fixedLoop = new List<Func<int>>();
        for (int i = 0; i < 3; i++)
        {
            int copy = i;                       // new variable per iteration
            fixedLoop.Add(() => copy);
        }
        Console.Write("copy fix:     ");
        foreach (Func<int> f in fixedLoop) Console.Write(f() + " ");   // 0 1 2
        Console.WriteLine();

        List<Func<int>> each = new List<Func<int>>();
        foreach (int n in new[] { 0, 1, 2 })
            each.Add(() => n);                  // foreach variable is fresh each iteration
        Console.Write("foreach:      ");
        foreach (Func<int> f in each) Console.Write(f() + " ");        // 0 1 2
        Console.WriteLine();

        int counter = 0;
        Action inc = () => counter++;           // the lambda and Main share the same variable
        inc(); inc();
        Console.WriteLine("shared counter = " + counter);
    }
}

using System;

class Program
{
    static void Main()
    {
        GC.Collect();
        int before = GC.CollectionCount(0);
        long sink = 0;
        for (int i = 0; i < 100000; i++)
        {
            byte[] temp = new byte[2000];       // short-lived garbage: cheap for the GC to drop
            temp[0] = 1; sink += temp.Length;
        }
        int allocating = GC.CollectionCount(0) - before;

        before = GC.CollectionCount(0);
        byte[] reused = new byte[2000];         // one buffer reused: no garbage at all
        for (int i = 0; i < 100000; i++)
        {
            reused[0] = 1; sink += reused.Length;
        }
        int reusing = GC.CollectionCount(0) - before;

        Console.WriteLine("allocating loop triggered gen0 collections: " + (allocating > 0));
        Console.WriteLine("reusing loop triggered gen0 collections:    " + (reusing > 0));
        Console.WriteLine("allocating caused more collections: " + (allocating > reusing));
        Console.WriteLine("work done: " + sink);
    }
}

using System;
using System.Collections.Concurrent;
using System.Threading;
using System.Collections.Generic;
using System.Threading.Tasks;

class AsyncCache
{
    readonly ConcurrentDictionary<int, Lazy<Task<string>>> map = new ConcurrentDictionary<int, Lazy<Task<string>>>();
    int loads;
    public int Loads { get { return loads; } }

    public async Task<string> Get(int key, bool failFirst)
    {
        // Lazy ensures only ONE caller runs the loader for a key
        Lazy<Task<string>> lazy = map.GetOrAdd(key, k => new Lazy<Task<string>>(() => Load(k, failFirst)));
        try { return await lazy.Value; }
        catch
        {
            // evict only this exact failed entry so the failure is not cached forever
            ((ICollection<KeyValuePair<int, Lazy<Task<string>>>>)map)
                .Remove(new KeyValuePair<int, Lazy<Task<string>>>(key, lazy));
            throw;
        }
    }

    async Task<string> Load(int k, bool fail)
    {
        int n = Interlocked.Increment(ref loads);
        await Task.Delay(50);
        if (fail && n == 1) throw new Exception("backend down");
        return "value-" + k;
    }
}

class Program
{
    static async Task Run()
    {
        AsyncCache c = new AsyncCache();
        Task<string>[] callers = new Task<string>[5];
        for (int i = 0; i < 5; i++) callers[i] = c.Get(7, false);
        string[] r = await Task.WhenAll(callers);
        Console.WriteLine("5 concurrent callers got " + r[0] + ", loader ran " + c.Loads + " time(s)");

        AsyncCache d = new AsyncCache();
        try { await d.Get(1, true); } catch (Exception e) { Console.WriteLine("first call failed: " + e.Message); }
        Console.WriteLine("retry after failure: " + await d.Get(1, true) + " (loads=" + d.Loads + ")");
    }
    static void Main() { Run().GetAwaiter().GetResult(); }
}

using System;
using System.Buffers;

class Program
{
    static int SumFirst(int n)
    {
        int[] buf = ArrayPool<int>.Shared.Rent(n);      // may be LARGER than n
        try
        {
            for (int i = 0; i < n; i++) buf[i] = i + 1;
            int sum = 0;
            for (int i = 0; i < n; i++) sum += buf[i];   // use n, never buf.Length
            Console.WriteLine("asked for " + n + ", got array of length >= n: " + (buf.Length >= n));
            return sum;
        }
        finally
        {
            ArrayPool<int>.Shared.Return(buf, clearArray: true);   // always return, exactly once
        }
    }

    static void Main()
    {
        Console.WriteLine("sum 1..10 = " + SumFirst(10));
        Console.WriteLine("sum 1..100 = " + SumFirst(100));
        int[] a = ArrayPool<int>.Shared.Rent(10);
        ArrayPool<int>.Shared.Return(a);
        int[] b = ArrayPool<int>.Shared.Rent(10);
        Console.WriteLine("same array handed out again: " + ReferenceEquals(a, b));
        ArrayPool<int>.Shared.Return(b);
    }
}

using System;

// Closed domain: a base type with a fixed set of outcomes
abstract class Outcome { }
sealed class Paid : Outcome { public decimal Amount; }
sealed class Declined : Outcome { public string Reason; }
sealed class NeedsOtp : Outcome { public string Phone; }

class Program
{
    static string Describe(Outcome o)
    {
        // C# 7 patterns: "is Type name" binds a typed variable (mcs-friendly form)
        if (o == null) return "no outcome";
        Paid p = o as Paid;
        if (p != null) return p.Amount > 100 ? "large payment " + p.Amount : "payment " + p.Amount;
        Declined d = o as Declined;
        if (d != null) return "declined: " + d.Reason;
        NeedsOtp n = o as NeedsOtp;
        if (n != null) return "send code to " + n.Phone;
        throw new InvalidOperationException("unhandled " + o.GetType().Name);   // new subclass: fails loudly
    }

    static void Main()
    {
        Outcome[] all = {
            new Paid { Amount = 250m }, new Paid { Amount = 20m },
            new Declined { Reason = "limit" }, new NeedsOtp { Phone = "***-1234" }, null };
        foreach (Outcome o in all) Console.WriteLine(Describe(o));

        object x = 5;
        if (x is int) Console.WriteLine("x is an int: " + (int)x);
    }
}
